import torch
import torch.nn as nn
import torch.nn.functional as F
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p39_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>
#include <vector>

std::vector<torch::Tensor> gru_forward_cuda(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> weight_ih_list,
    std::vector<torch::Tensor> weight_hh_list,
    std::vector<torch::Tensor> bias_ih_list,
    std::vector<torch::Tensor> bias_hh_list
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gru_forward", &gru_forward_cuda, "Custom GRU forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <vector>

// Persistent cuBLAS handle
static cublasHandle_t g_cublas_handle = nullptr;

static void ensure_cublas() {
    if (g_cublas_handle == nullptr) {
        cublasCreate(&g_cublas_handle);
    }
}

// Fused GRU gate kernel:
// gates_ih: [batch, 3*hidden] - input projection (r_ih, z_ih, n_ih)
// gates_hh: [batch, 3*hidden] - recurrent projection (r_hh, z_hh, n_hh)
// h_prev:   [batch, hidden]
// h_out:    [batch, hidden]
// bias_ih:  [3*hidden]
// bias_hh:  [3*hidden]
__global__ void gru_cell_kernel(
    const float* __restrict__ gates_ih,
    const float* __restrict__ gates_hh,
    const float* __restrict__ h_prev,
    float* __restrict__ h_out,
    const float* __restrict__ bias_ih,
    const float* __restrict__ bias_hh,
    int batch_size,
    int hidden_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * hidden_size) return;

    int b = idx / hidden_size;
    int h = idx % hidden_size;

    int base_ih = b * 3 * hidden_size;
    int base_hh = b * 3 * hidden_size;

    // Gate indices
    int r_idx = h;
    int z_idx = hidden_size + h;
    int n_idx = 2 * hidden_size + h;

    float r_ih = gates_ih[base_ih + r_idx] + bias_ih[r_idx];
    float r_hh = gates_hh[base_hh + r_idx] + bias_hh[r_idx];
    float r = 1.0f / (1.0f + __expf(-(r_ih + r_hh)));

    float z_ih = gates_ih[base_ih + z_idx] + bias_ih[z_idx];
    float z_hh = gates_hh[base_hh + z_idx] + bias_hh[z_idx];
    float z = 1.0f / (1.0f + __expf(-(z_ih + z_hh)));

    float n_ih_val = gates_ih[base_ih + n_idx] + bias_ih[n_idx];
    float n_hh_val = gates_hh[base_hh + n_idx] + bias_hh[n_idx];
    float n = tanhf(n_ih_val + r * n_hh_val);

    float h_prev_val = h_prev[b * hidden_size + h];
    h_out[b * hidden_size + h] = (1.0f - z) * n + z * h_prev_val;
}

std::vector<torch::Tensor> gru_forward_cuda(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> weight_ih_list,
    std::vector<torch::Tensor> weight_hh_list,
    std::vector<torch::Tensor> bias_ih_list,
    std::vector<torch::Tensor> bias_hh_list
) {
    ensure_cublas();

    // x: [seq_len, batch, input_size]
    int seq_len    = x.size(0);
    int batch_size = x.size(1);
    int input_size = x.size(2);
    int num_layers = weight_ih_list.size();
    int hidden_size = weight_hh_list[0].size(1);
    int gate_size   = 3 * hidden_size;

    // Ensure contiguous
    x = x.contiguous();
    h0 = h0.contiguous();

    // Output: [seq_len, batch, hidden]
    auto output = torch::empty({seq_len, batch_size, hidden_size}, x.options());
    // h_n: [num_layers, batch, hidden]
    auto h_n = torch::empty({num_layers, batch_size, hidden_size}, x.options());

    // Allocate gate buffers
    auto gates_ih = torch::empty({batch_size, gate_size}, x.options());
    auto gates_hh = torch::empty({batch_size, gate_size}, x.options());

    const float alpha = 1.0f, beta = 0.0f;

    // current layer input starts as x
    // We'll build layer_input as a [seq_len, batch, feat] tensor
    torch::Tensor layer_input = x;

    for (int layer = 0; layer < num_layers; layer++) {
        // weight_ih: [gate_size, in_feat], weight_hh: [gate_size, hidden]
        auto W_ih = weight_ih_list[layer].contiguous(); // [gate_size, in_feat]
        auto W_hh = weight_hh_list[layer].contiguous(); // [gate_size, hidden]
        auto b_ih = bias_ih_list[layer].contiguous();    // [gate_size]
        auto b_hh = bias_hh_list[layer].contiguous();    // [gate_size]

        int in_feat = W_ih.size(1);

        // h_prev for this layer: h0[layer]
        auto h_prev = h0[layer].contiguous().clone(); // [batch, hidden]

        // layer_output: [seq_len, batch, hidden]
        auto layer_output = torch::empty({seq_len, batch_size, hidden_size}, x.options());

        for (int t = 0; t < seq_len; t++) {
            // x_t: [batch, in_feat]
            auto x_t = layer_input[t].contiguous();

            // gates_ih = x_t @ W_ih.T  => [batch, gate_size]
            // cuBLAS is column-major: C = A*B => in row-major: C^T = B^T * A^T
            // We want gates_ih[batch, gate_size] = x_t[batch, in_feat] @ W_ih.T[in_feat, gate_size]
            // In cuBLAS col-major: C(gate_size, batch) = W_ih(gate_size, in_feat) * x_t^T(in_feat, batch)
            // i.e. cublasSgemm(handle, CUBLAS_OP_T, CUBLAS_OP_N, gate_size, batch, in_feat, ...)
            // Actually: C = op(A)*op(B), A=W_ih[gate_size,in_feat], op=T => [in_feat,gate_size]
            // No wait: result should be [batch, gate_size] in row-major = [gate_size, batch] in col-major
            // = W_ih(row-major [gate_size, in_feat], col-major [in_feat, gate_size]) * x_t^T(col-major [in_feat, batch])
            // cublasSgemm: op(A)[m,k] * op(B)[k,n] = C[m,n], all col-major
            // We want C[gate_size, batch] = W_ih[gate_size, in_feat] * x_t^T[in_feat, batch]
            // A = W_ih stored row-major [gate_size, in_feat] = col-major [in_feat, gate_size], so op=CUBLAS_OP_T, lda=in_feat
            // B = x_t stored row-major [batch, in_feat] = col-major [in_feat, batch], so op=CUBLAS_OP_N, ldb=in_feat
            // m=gate_size, n=batch, k=in_feat
            cublasSgemm(
                g_cublas_handle,
                CUBLAS_OP_T, CUBLAS_OP_N,
                gate_size, batch_size, in_feat,
                &alpha,
                W_ih.data_ptr<float>(), in_feat,
                x_t.data_ptr<float>(), in_feat,
                &beta,
                gates_ih.data_ptr<float>(), gate_size
            );

            // gates_hh = h_prev @ W_hh.T => [batch, gate_size]
            cublasSgemm(
                g_cublas_handle,
                CUBLAS_OP_T, CUBLAS_OP_N,
                gate_size, batch_size, hidden_size,
                &alpha,
                W_hh.data_ptr<float>(), hidden_size,
                h_prev.data_ptr<float>(), hidden_size,
                &beta,
                gates_hh.data_ptr<float>(), gate_size
            );

            // Fused gate activation kernel
            auto h_out = layer_output[t];
            int total = batch_size * hidden_size;
            int threads = 256;
            int blocks = (total + threads - 1) / threads;
            gru_cell_kernel<<<blocks, threads>>>(
                gates_ih.data_ptr<float>(),
                gates_hh.data_ptr<float>(),
                h_prev.data_ptr<float>(),
                h_out.data_ptr<float>(),
                b_ih.data_ptr<float>(),
                b_hh.data_ptr<float>(),
                batch_size,
                hidden_size
            );

            // Update h_prev
            h_prev = layer_output[t].contiguous();
        }

        h_n[layer] = h_prev;
        layer_input = layer_output;
    }

    output.copy_(layer_input);
    return {output, h_n};
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.gru = nn.GRU(input_size, hidden_size, num_layers, bias, batch_first, dropout=0, bidirectional=False)
        self.gru.flatten_parameters()
        self._input_size = input_size
        self._hidden_size = hidden_size
        self._num_layers = num_layers
        self._bias = bias
        self._batch_first = batch_first
        # <<<END_IMPROVE>>>

    def forward(self, x,h0):
        # <<<IMPROVE:forward_stmt_1>>>
        """
                :param x: The input tensor, shape (seq_len, batch_size, input_size) if batch_first=False, otherwise (batch_size, seq_len, input_size)
                :param h_0: The initial hidden state for the input sequence, shape (num_layers * num_directions, batch_size, hidden_size) (default: None)
                :return: output, h_n
                    - output: The output features (h_t) from the last layer of the GRU, for each t, shape (seq_len, batch_size, num_directions * hidden_size) if batch_first=False, otherwise (batch_size, seq_len, num_directions * hidden_size)
                    - h_n: The hidden state for t = seq_len, shape (num_layers * num_directions, batch_size, hidden_size)
                """
        x = x.contiguous()
        h0 = h0.contiguous()
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        # Try fast path: contiguous float32 CUDA tensors, no batch_first
        if (x.is_cuda and x.dtype == torch.float32 and h0.is_cuda and h0.dtype == torch.float32
                and not self._batch_first):
            try:
                ext = _stark_get_extension()
                weight_ih_list = [getattr(self.gru, f'weight_ih_l{i}') for i in range(self._num_layers)]
                weight_hh_list = [getattr(self.gru, f'weight_hh_l{i}') for i in range(self._num_layers)]
                if self._bias:
                    bias_ih_list = [getattr(self.gru, f'bias_ih_l{i}') for i in range(self._num_layers)]
                    bias_hh_list = [getattr(self.gru, f'bias_hh_l{i}') for i in range(self._num_layers)]
                else:
                    bias_ih_list = [torch.zeros(3 * self._hidden_size, device=x.device) for _ in range(self._num_layers)]
                    bias_hh_list = [torch.zeros(3 * self._hidden_size, device=x.device) for _ in range(self._num_layers)]
                output, h_n = ext.gru_forward(x, h0, weight_ih_list, weight_hh_list, bias_ih_list, bias_hh_list)
            except Exception:
                output, h_n = self.gru(x, h0)
        else:
            output, h_n = self.gru(x, h0)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        return output
        # <<<END_IMPROVE>>>

