// Fused GRU gate kernel: given gates_x [batch, 3H] and gates_h [batch, 3H],
// compute r, z, n and update hidden state h [batch, H] in-place.
__global__ void gru_cell_kernel(
    const float* __restrict__ gates_x,  // [batch, 3*H]
    const float* __restrict__ gates_h,  // [batch, 3*H]
    float* __restrict__ h,              // [batch, H] in/out
    int batch_size,
    int hidden_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * hidden_size;
    if (idx >= total) return;

    int b = idx / hidden_size;
    int hid = idx % hidden_size;
    int H = hidden_size;

    // gates layout: [r | z | n] each of size H
    float gx_r = gates_x[b * 3 * H + hid];
    float gx_z = gates_x[b * 3 * H + H + hid];
    float gx_n = gates_x[b * 3 * H + 2 * H + hid];

    float gh_r = gates_h[b * 3 * H + hid];
    float gh_z = gates_h[b * 3 * H + H + hid];
    float gh_n = gates_h[b * 3 * H + 2 * H + hid];

    // r = sigmoid(gx_r + gh_r)
    float r = 1.0f / (1.0f + __expf(-(gx_r + gh_r)));
    // z = sigmoid(gx_z + gh_z)
    float z = 1.0f / (1.0f + __expf(-(gx_z + gh_z)));
    // n = tanh(gx_n + r * gh_n)  [PyTorch GRU formula]
    float n = tanhf(gx_n + r * gh_n);

    float h_prev = h[b * H + hid];
    // h_new = (1 - z) * n + z * h_prev
    h[b * H + hid] = (1.0f - z) * n + z * h_prev;
}

torch::Tensor gru_gemm_fused_forward(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> w_ih,
    std::vector<torch::Tensor> w_hh,
    std::vector<torch::Tensor> b_ih,
    std::vector<torch::Tensor> b_hh
) {
    // x: [seq_len, batch_size, input_size]
    // h0: [num_layers, batch_size, hidden_size]
    int seq_len    = x.size(0);
    int batch_size = x.size(1);
    int hidden_size = h0.size(2);
    int num_layers  = (int)w_ih.size();

    // Make sure all tensors are contiguous
    x = x.contiguous();
    h0 = h0.contiguous();

    // Output tensor: [seq_len, batch_size, hidden_size]
    auto output = torch::empty({seq_len, batch_size, hidden_size}, x.options());

    // Current hidden states for each layer: [num_layers, batch_size, hidden_size]
    // We'll keep them as a vector of [batch, H] tensors
    std::vector<torch::Tensor> h_cur(num_layers);
    for (int l = 0; l < num_layers; l++) {
        h_cur[l] = h0[l].clone();  // [batch, H]
    }

    // Precompute transposed weights for efficiency (avoid repeated .t() calls)
    std::vector<torch::Tensor> wih_t(num_layers), whh_t(num_layers);
    for (int l = 0; l < num_layers; l++) {
        wih_t[l] = w_ih[l].t().contiguous();  // [input/hidden, 3H]
        whh_t[l] = w_hh[l].t().contiguous();  // [hidden, 3H]
