// Fused GRU cell kernel: gates_ih_t has bias_ih already folded in (via at::addmm),
// gates_hh has the raw recurrent GEMM output; bias_hh is added here in-register.
__global__ void gru_cell_kernel_fused(
    const float* __restrict__ gates_ih_t,   // [batch_size, 3*hidden_size], bias_ih folded
    const float* __restrict__ gates_hh_raw, // [batch_size, 3*hidden_size], no bias yet
    const float* __restrict__ bias_hh,      // [3*hidden_size]
    const float* __restrict__ h_prev,
    float* __restrict__ h_out,
    int batch_size,
    int hidden_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * hidden_size) return;

    int b = idx / hidden_size;
    int h = idx % hidden_size;

    int base = b * 3 * hidden_size;

    float r_ih  = gates_ih_t[base + h];
    float r_hh  = gates_hh_raw[base + h] + bias_hh[h];
    float r = 1.0f / (1.0f + __expf(-(r_ih + r_hh)));

    float z_ih  = gates_ih_t[base + hidden_size + h];
    float z_hh  = gates_hh_raw[base + hidden_size + h] + bias_hh[hidden_size + h];
    float z = 1.0f / (1.0f + __expf(-(z_ih + z_hh)));

    float n_ih  = gates_ih_t[base + 2*hidden_size + h];
    float n_hh  = gates_hh_raw[base + 2*hidden_size + h] + bias_hh[2*hidden_size + h];
    float n = tanhf(n_ih + r * n_hh);

    float h_prev_val = h_prev[b * hidden_size + h];
    h_out[b * hidden_size + h] = (1.0f - z) * n + z * h_prev_val;
}

