    int v = idx % hidden_vec;
    int gate_stride4 = hidden_vec;
    int base = b * 3 * gate_stride4 + v;
    int h_base = b * hidden_vec + v;

    float4 ih_r = gates_ih_t4[base];
    float4 hh_r = gates_hh_raw4[base];
    float4 bh_r = bias_hh4[v];

    float4 ih_z = gates_ih_t4[base + gate_stride4];
    float4 hh_z = gates_hh_raw4[base + gate_stride4];
    float4 bh_z = bias_hh4[gate_stride4 + v];

    float4 ih_n = gates_ih_t4[base + 2 * gate_stride4];
    float4 hh_n = gates_hh_raw4[base + 2 * gate_stride4];
    float4 bh_n = bias_hh4[2 * gate_stride4 + v];

    float4 hp = h_prev4[h_base];
    float4 out;

    float r0 = sigmoidf_cuda(ih_r.x + hh_r.x + bh_r.x);
    float r1 = sigmoidf_cuda(ih_r.y + hh_r.y + bh_r.y);
    float r2 = sigmoidf_cuda(ih_r.z + hh_r.z + bh_r.z);
    float r3 = sigmoidf_cuda(ih_r.w + hh_r.w + bh_r.w);

    float z0 = sigmoidf_cuda(ih_z.x + hh_z.x + bh_z.x);
    float z1 = sigmoidf_cuda(ih_z.y + hh_z.y + bh_z.y);
    float z2 = sigmoidf_cuda(ih_z.z + hh_z.z + bh_z.z);
    float z3 = sigmoidf_cuda(ih_z.w + hh_z.w + bh_z.w);

    float n0 = tanhf(ih_n.x + r0 * (hh_n.x + bh_n.x));
    float n1 = tanhf(ih_n.y + r1 * (hh_n.y + bh_n.y));
    float n2 = tanhf(ih_n.z + r2 * (hh_n.z + bh_n.z));
    float n3 = tanhf(ih_n.w + r3 * (hh_n.w + bh_n.w));

    out.x = (1.0f - z0) * n0 + z0 * hp.x;
    out.y = (1.0f - z1) * n1 + z1 * hp.y;
    out.z = (1.0f - z2) * n2 + z2 * hp.z;
    out.w = (1.0f - z3) * n3 + z3 * hp.w;

    h_out4[h_base] = out;
}

std::vector<torch::Tensor> gru_forward_cuda(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> weight_ih_list,
    std::vector<torch::Tensor> weight_hh_list,
    std::vector<torch::Tensor> bias_ih_list,
    std::vector<torch::Tensor> bias_hh_list
) {
    ensure_cublas();
    cublasSetStream(g_cublas_handle, at::cuda::getCurrentCUDAStream());

    int seq_len = x.size(0);
    int batch_size = x.size(1);
    int num_layers = (int)weight_ih_list.size();
    int hidden_size = (int)weight_hh_list[0].size(1);
    int gate_size = 3 * hidden_size;

    auto h_n = torch::empty({num_layers, batch_size, hidden_size}, x.options());
    auto gates_hh = torch::empty({batch_size, gate_size}, x.options());

    const float alpha = 1.0f;
    const float beta_zero = 0.0f;
    torch::Tensor layer_input = x;

    for (int layer = 0; layer < num_layers; layer++) {
        auto W_ih = weight_ih_list[layer].contiguous();
        auto W_hh = weight_hh_list[layer].contiguous();
        auto b_ih = bias_ih_list[layer].contiguous();
        auto b_hh = bias_hh_list[layer].contiguous();

        int in_feat = (int)W_ih.size(1);
        auto layer_flat = layer_input.reshape({seq_len * batch_size, in_feat});
        auto gates_ih_all = at::addmm(b_ih, layer_flat, W_ih.t()).view({seq_len, batch_size, gate_size}).contiguous();

        auto h_prev = h0[layer].contiguous().clone();
        auto layer_output = torch::empty({seq_len, batch_size, hidden_size}, x.options());

        int threads = 256;
        bool use_vec4 = (hidden_size % 4) == 0;
        int launch_elems = use_vec4 ? batch_size * (hidden_size / 4) : batch_size * hidden_size;
        int blocks = (launch_elems + threads - 1) / threads;

        for (int t = 0; t < seq_len; t++) {
            cublasSgemm(
                g_cublas_handle,
                CUBLAS_OP_T,
                CUBLAS_OP_N,
                gate_size,
                batch_size,
                hidden_size,
                &alpha,
                W_hh.data_ptr<float>(),
                hidden_size,
                h_prev.data_ptr<float>(),
                hidden_size,
                &beta_zero,
                gates_hh.data_ptr<float>(),
                gate_size
            );

            auto h_out = layer_output[t];
            if (use_vec4) {
                gru_cell_kernel_fused_vec4<<<blocks, threads>>>(
                    reinterpret_cast<const float4*>(gates_ih_all[t].data_ptr<float>()),
                    reinterpret_cast<const float4*>(gates_hh.data_ptr<float>()),
                    reinterpret_cast<const float4*>(b_hh.data_ptr<float>()),
                    reinterpret_cast<const float4*>(h_prev.data_ptr<float>()),
                    reinterpret_cast<float4*>(h_out.data_ptr<float>()),
                    batch_size,
                    hidden_size
                );
            } else {
                gru_cell_kernel_fused_scalar<<<blocks, threads>>>(
                    gates_ih_all[t].data_ptr<float>(),
                    gates_hh.data_ptr<float>(),
                    b_hh.data_ptr<float>(),
                    h_prev.data_ptr<float>(),
                    h_out.data_ptr<float>(),
                    batch_size,
                    hidden_size
                );
            }

            h_prev = layer_output[t].contiguous();
        }

        h_n[layer] = h_prev;
        layer_input = layer_output;
    }

    return {layer_input.contiguous(), h_n};
}
